<template>
  <div class="library-page">
    <PageTitle eyebrow="RESOURCE LIBRARY" title="资料库" description="根据当前画像和学习情况结合知识库生成的专属学习资料">
      <template #actions><RouterLink class="button button--primary" to="/learnmate-chat"><Sparkles :size="15" />生成资料</RouterLink></template>
    </PageTitle>
    <section class="library-context surface">
      <div class="context-copy"><span class="context-icon"><Target :size="18" /></span><div><p class="eyebrow">PERSONALIZED FOR YOU</p><h2>{{ profile.direction || '你的学习方向' }}</h2><p>{{ profile.stage || '基础阶段' }} · {{ profile.goal || '建立稳定的学习节奏' }}</p></div></div>
      <div class="context-stats"><div><strong>{{ filteredResources.length }}</strong><span>匹配材料</span></div><div><strong>{{ unreadCount }}</strong><span>待阅读</span></div><div><strong>{{ favoriteCount }}</strong><span>已收藏</span></div></div>
    </section>
    <div class="library-toolbar"><div class="filter-tabs" role="tablist" aria-label="材料类型"><button v-for="tab in tabs" :key="tab.key" type="button" :class="{ 'is-active': activeType === tab.key }" @click="activeType = tab.key">{{ tab.label }}<span>{{ countByType(tab.key) }}</span></button></div><label class="search-box"><Search :size="16" /><span class="sr-only">搜索资料</span><input v-model.trim="searchTerm" type="search" placeholder="搜索主题、来源或标签" /></label></div>
    <div v-if="loading" class="library-state surface"><LoaderCircle class="spin" :size="20" />正在同步你的资料库</div>
    <div v-else-if="errorMessage" class="library-state library-state--error surface"><CircleAlert :size="20" /><div><strong>资料库暂时无法加载</strong><p>{{ errorMessage }}</p></div><button class="button button--quiet" type="button" @click="loadResources">重试</button></div>
    <div v-else-if="!filteredResources.length" class="library-state surface"><BookOpen :size="20" /><div><strong>还没有匹配的材料</strong><p>调整筛选条件，或让 LearnMate 根据当前目标生成一份新资料。</p></div><RouterLink class="button button--primary" to="/learnmate-chat">开始生成</RouterLink></div>
    <div v-else class="resource-list"><article v-for="resource in filteredResources" :key="resource.resource_id" class="resource-row surface" :class="{ 'is-read': resource.is_read }"><div class="resource-mark" :class="`mark-${resource.resource_type}`"><FileText v-if="resource.resource_type === 'document' || resource.resource_type === 'reading'" :size="19" /><PlayCircle v-else-if="resource.resource_type === 'video' || resource.resource_type === 'external_video'" :size="19" /><Code2 v-else-if="resource.resource_type === 'code' || resource.resource_type === 'template'" :size="19" /><ListChecks v-else :size="19" /></div><div class="resource-main"><div class="resource-title-line"><h2>{{ resource.topic || '未命名学习材料' }}</h2><span class="type-label">{{ typeLabel(resource.resource_type) }}</span></div><p class="resource-reason"><span>匹配理由</span>{{ resource.match_reason }}</p><div class="resource-meta"><span><BarChart3 :size="13" />{{ difficultyLabel(resource) }}</span><span><Compass :size="13" />{{ resource.source_label }}</span><span><Clock3 :size="13" />{{ formatDate(resource.created_at) }}</span></div></div><div class="resource-actions"><button class="icon-button" type="button" :class="{ 'is-favorite': resource.favorited }" :aria-label="resource.favorited ? '取消收藏' : '收藏资料'" :title="resource.favorited ? '取消收藏' : '收藏资料'" @click="toggleFavorite(resource)"><Star :size="16" :fill="resource.favorited ? 'currentColor' : 'none'" /></button><button class="button button--quiet open-button" type="button" @click="openPreview(resource)">打开 <ArrowUpRight :size="14" /></button></div></article></div>
    <div v-if="previewResource" class="preview-backdrop" @click.self="previewResource = null"><section class="preview-modal surface" role="dialog" aria-modal="true" aria-labelledby="preview-title"><button class="preview-close icon-button" type="button" aria-label="关闭预览" @click="previewResource = null"><X :size="17" /></button><p class="eyebrow">{{ typeLabel(previewResource.resource_type) }} · {{ difficultyLabel(previewResource) }}</p><h2 id="preview-title">{{ previewResource.topic }}</h2><p class="preview-source">{{ previewResource.source_label }} · {{ previewResource.match_reason }}</p><div class="preview-content">{{ previewResource.preview || '这份材料还没有可预览的摘要，打开学习工作区查看完整内容。' }}</div><div class="preview-footer"><button class="button button--quiet" type="button" @click="previewResource = null">稍后阅读</button><button class="button button--primary" type="button" @click="markAndClose(previewResource)">标记为已读</button></div></section></div>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ArrowUpRight, BarChart3, BookOpen, CircleAlert, Clock3, Code2, Compass, FileText, ListChecks, LoaderCircle, PlayCircle, Search, Sparkles, Star, Target, X } from 'lucide-vue-next'
import PageTitle from '@/shared/ui/PageTitle.vue'
import { learningApi } from '@/shared/api/learningApi'
import { resourceApi } from '@/shared/api/resourceApi'

const unwrap = (response) => response?.data?.data ?? response?.data ?? []
const loading = ref(true); const errorMessage = ref(''); const resources = ref([]); const activeType = ref('all'); const searchTerm = ref(''); const previewResource = ref(null)
const profile = reactive({ direction: '', goal: '', stage: '' })
const tabs = [{ key: 'all', label: '全部' }, { key: 'document', label: '文档' }, { key: 'video', label: '视频' }, { key: 'code', label: '代码模板' }, { key: 'exercise', label: '练习题' }]
const fallbackResources = [{ resource_id: 'demo-doc', topic: '从问题拆解到可验证的学习计划', resource_type: 'document', preview: '用目标、证据和下一步行动，把模糊的问题拆成可执行的学习任务。', difficulty: '入门', match_reason: '适合你当前的基础阶段，先建立通用方法。', source_label: 'LearnMate 学习路径', created_at: new Date().toISOString(), favorited: false, is_read: false }, { resource_id: 'demo-video', topic: '把抽象概念讲清楚：示例驱动的讲解', resource_type: 'video', preview: '一段围绕真实案例展开的短视频，帮助你把新概念迁移到目标场景。', difficulty: '进阶', match_reason: '与你的学习目标相关，适合完成基础讲解后观看。', source_label: 'LearnMate 推荐', created_at: new Date().toISOString(), favorited: false, is_read: false }, { resource_id: 'demo-code', topic: '可复用的项目起步模板', resource_type: 'code', preview: '包含目录结构、最小运行示例和待补充的实践清单。', difficulty: '中等', match_reason: '匹配当前实践阶段，可直接作为下一步任务的起点。', source_label: '学习路径代码模板', created_at: new Date().toISOString(), favorited: false, is_read: false }, { resource_id: 'demo-exercise', topic: '知识点迁移练习：做出你的判断', resource_type: 'exercise', preview: '通过 5 道情境题检验你是否能在新场景中使用刚学到的方法。', difficulty: '中等', match_reason: '针对近期掌握度较低的知识点，建议优先完成。', source_label: 'LearnMate 练习库', created_at: new Date().toISOString(), favorited: false, is_read: false }]
const typeLabel = (type) => ({ document: '文档', reading: '阅读材料', video: '视频', external_video: '视频', code: '代码模板', template: '代码模板', exercise: '练习题', case: '案例' }[type] || '学习材料')
const difficultyLabel = (resource) => resource.difficulty || ({ exercise: '中等', document: '入门', video: '进阶', code: '中等' }[resource.resource_type] || '适中')
const normalize = (item) => ({ ...item, match_reason: item.match_reason || item.reason || '与你当前学习方向和阶段匹配', source_label: item.source_label || item.source || (item.owner_user_id ? '你的学习路径' : 'LearnMate 推荐'), is_read: Boolean(item.is_read), favorited: Boolean(item.favorited) })
const filteredResources = computed(() => resources.value.filter((item) => { const typeMatch = activeType.value === 'all' || item.resource_type === activeType.value || (activeType.value === 'video' && item.resource_type === 'external_video') || (activeType.value === 'code' && item.resource_type === 'template'); const needle = searchTerm.value.toLowerCase(); return typeMatch && (!needle || [item.topic, item.match_reason, item.source_label, typeLabel(item.resource_type)].join(' ').toLowerCase().includes(needle)) }))
const countByType = (type) => type === 'all' ? resources.value.length : resources.value.filter((item) => item.resource_type === type || (type === 'video' && item.resource_type === 'external_video') || (type === 'code' && item.resource_type === 'template')).length
const unreadCount = computed(() => resources.value.filter((item) => !item.is_read).length); const favoriteCount = computed(() => resources.value.filter((item) => item.favorited).length)
async function loadResources() { loading.value = true; errorMessage.value = ''; try { const [list, overviewResponse] = await Promise.all([resourceApi.list(), learningApi.getOverview()]); const overview = unwrap(overviewResponse) || {}; Object.assign(profile, { direction: overview.profile?.direction || overview.subjects?.[0]?.name || '', goal: overview.profile?.goal || overview.goals?.[0]?.title || '', stage: overview.path?.stage || overview.path?.current_node || '' }); resources.value = (Array.isArray(list) && list.length ? list : fallbackResources).map(normalize) } catch (error) { resources.value = fallbackResources; errorMessage.value = error?.message || '请稍后重试' } finally { loading.value = false } }
async function toggleFavorite(resource) { resource.favorited = !resource.favorited; if (String(resource.resource_id).startsWith('demo-')) return; try { await resourceApi.favorite(resource.resource_id) } catch { resource.favorited = !resource.favorited } }
async function markRead(resource) { resource.is_read = true; if (!String(resource.resource_id).startsWith('demo-')) await resourceApi.markRead(resource.resource_id).catch(() => {}) }
function openPreview(resource) { previewResource.value = resource; markRead(resource) }; function markAndClose(resource) { markRead(resource); previewResource.value = null }
function formatDate(value) { if (!value) return '最近更新'; const date = new Date(value); return Number.isNaN(date.getTime()) ? '最近更新' : date.toLocaleDateString('zh-CN', { month: 'numeric', day: 'numeric' }) + ' 更新' }
onMounted(loadResources)
</script>

